INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Pediatrics', 'Growth & Development', 'mcq-single', 'Knowledge', 'Which developmental milestone is typically achieved by a healthy infant by approximately 6 months of age?', '[{"letter":"A","text":"Walking independently","correct":false},{"letter":"B","text":"Sitting with support","correct":true},{"letter":"C","text":"Speaking two word sentences","correct":false},{"letter":"D","text":"Riding a tricycle","correct":false}]'::jsonb, 'Most infants can sit with support around 6 months.', true, 'ungrouped', 'zero-one');
INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Pediatrics', 'Immunization', 'mcq-single', 'Knowledge', 'Which vaccine is commonly administered to prevent tuberculosis?', '[{"letter":"A","text":"BCG","correct":true},{"letter":"B","text":"MMR","correct":false},{"letter":"C","text":"DPT","correct":false},{"letter":"D","text":"OPV","correct":false}]'::jsonb, 'BCG is used primarily for protection against tuberculosis.', true, 'ungrouped', 'zero-one');
