INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Physiology', 'Cardiovascular', 'mcq-single', 'Knowledge', 'What is the normal primary pacemaker of the human heart?', '[{"letter":"A","text":"AV node","correct":false},{"letter":"B","text":"Bundle of His","correct":false},{"letter":"C","text":"SA node","correct":true},{"letter":"D","text":"Purkinje fibers","correct":false}]'::jsonb, 'The sinoatrial node generates the normal electrical impulse.', true, 'ungrouped', 'zero-one');
INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Physiology', 'Respiratory', 'mcq-multi', 'Application', 'Which factors can increase respiratory rate?', '[{"letter":"A","text":"Exercise","correct":true},{"letter":"B","text":"Fever","correct":true},{"letter":"C","text":"Metabolic acidosis","correct":true},{"letter":"D","text":"Severe central nervous system depression","correct":false},{"letter":"E","text":"Anxiety","correct":true}]'::jsonb, 'Exercise, fever, acidosis, and anxiety can stimulate ventilation.', true, 'ungrouped', 'zero-one');
