INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('General Medicine', 'Cardiology', 'mcq-single', 'Application', 'A patient presents with crushing central chest pain radiating to the left arm. Which investigation is most important initially?', '[{"letter":"A","text":"ECG","correct":true},{"letter":"B","text":"MRI brain","correct":false},{"letter":"C","text":"Endoscopy","correct":false},{"letter":"D","text":"Abdominal ultrasound","correct":false}]'::jsonb, 'An ECG should be obtained primarily in suspected acute coronary syndrome.', true, 'ungrouped', 'zero-one');
