INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('General Medicine', 'Respiratory Medicine', 'mcq-single', 'Application', 'Which finding is most characteristic of an acute asthma attack?', '[{"letter":"A","text":"Wheezing","correct":true},{"letter":"B","text":"Jaundice","correct":false},{"letter":"C","text":"Hematuria","correct":false},{"letter":"D","text":"Bradykinesia","correct":false}]'::jsonb, 'Wheezing is a common finding caused by airway narrowing during asthma exacerbation.', true, 'ungrouped', 'zero-one');
