INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Surgery', 'Acute Abdomen', 'mcq-single', 'Analysis', 'A patient presents with severe right lower abdominal pain, fever, nausea, and loss of appetite. Which condition should be strongly considered?', '[{"letter":"A","text":"Acute appendicitis","correct":true},{"letter":"B","text":"Migraine","correct":false},{"letter":"C","text":"Otitis media","correct":false},{"letter":"D","text":"Acute glaucoma","correct":false}]'::jsonb, 'Right lower quadrant pain with fever, nausea, and anorexia suggests acute appendicitis.', true, 'ungrouped', 'zero-one');
