INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Anatomy', 'Lower Limb', 'mcq-single', 'Knowledge', 'Which muscle is primarily responsible for extension of the knee?', '[{"letter":"A","text":"Biceps femoris","correct":false},{"letter":"B","text":"Quadriceps femoris","correct":true},{"letter":"C","text":"Gastrocnemius","correct":false},{"letter":"D","text":"Sartorius","correct":false}]'::jsonb, 'The quadriceps femoris group extends the knee.', true, 'ungrouped', 'zero-one');
