INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Physiology', 'Endocrine', 'mcq-single', 'Knowledge', 'Which hormone lowers blood glucose concentration?', '[{"letter":"A","text":"Glucagon","correct":false},{"letter":"B","text":"Cortisol","correct":false},{"letter":"C","text":"Insulin","correct":true},{"letter":"D","text":"Adrenaline","correct":false}]'::jsonb, 'Insulin lowers blood glucose by promoting glucose uptake and storage.', true, 'ungrouped', 'zero-one');
