INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Anatomy', 'Head & Neck', 'mcq-single', 'Knowledge', 'Which cranial nerve is responsible for facial expression?', '[{"letter":"A","text":"Trigeminal nerve","correct":false},{"letter":"B","text":"Facial nerve","correct":true},{"letter":"C","text":"Vagus nerve","correct":false},{"letter":"D","text":"Hypoglossal nerve","correct":false}]'::jsonb, 'The facial nerve supplies the muscles of facial expression.', true, 'ungrouped', 'zero-one');
INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Physiology', 'Blood', 'mcq-multi', 'Knowledge', 'Which are functions of red blood cells?', '[{"letter":"A","text":"Transport oxygen","correct":true},{"letter":"B","text":"Transport some carbon dioxide","correct":true},{"letter":"C","text":"Contribute to blood buffering","correct":true},{"letter":"D","text":"Produce antibodies","correct":false}]'::jsonb, 'Red blood cells transport oxygen, carry some carbon dioxide, and contribute to acid-base buffering.', true, 'ungrouped', 'zero-one');
INSERT INTO questions (category, subcategory, type, difficulty, stem, options, rationale, is_published, group_type, marking_scheme) VALUES ('Biochemistry', 'Vitamins', 'mcq-single', 'Knowledge', 'Deficiency of which vitamin can lead to scurvy?', '[{"letter":"A","text":"Vitamin A","correct":false},{"letter":"B","text":"Vitamin C","correct":true},{"letter":"C","text":"Vitamin D","correct":false},{"letter":"D","text":"Vitamin K","correct":false}]'::jsonb, 'Vitamin C deficiency causes scurvy.', true, 'ungrouped', 'zero-one');